CREATE OR REPLACE FUNCTION "public"."calculate_session_credits"("p_session_id" "uuid", "p_booking_time" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_base_credits INTEGER;
  v_total_multiplier DECIMAL := 1.0;
  v_session RECORD;
  v_gym RECORD;
  v_rule RECORD;
  v_spots_remaining INTEGER;
  v_capacity_percentage DECIMAL;
  v_hours_until_class DECIMAL;
  v_final_credits INTEGER;
  v_min_credits INTEGER := 3;
  v_max_credits INTEGER := 15;
BEGIN
  -- Get session details
  SELECT s.*, g.rate_floor, g.drop_in_price, g.max_platform_spots
  INTO v_session
  FROM sessions s
  JOIN gyms g ON s.gym_id = g.id
  WHERE s.id = p_session_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_base_credits := v_session.base_credits;

  -- Calculate spots remaining
  SELECT (v_session.max_capacity - COUNT(b.id))
  INTO v_spots_remaining
  FROM bookings b
  WHERE b.session_id = p_session_id
  AND b.status = 'confirmed';

  v_capacity_percentage := ((v_session.max_capacity - v_spots_remaining)::DECIMAL / v_session.max_capacity) * 100;

  -- Calculate hours until class
  v_hours_until_class := EXTRACT(EPOCH FROM (v_session.date + v_session.time - p_booking_time)) / 3600;

  -- Apply pricing rules
  FOR v_rule IN 
    SELECT * FROM pricing_rules 
    WHERE is_active = true 
    ORDER BY priority
  LOOP
    CASE v_rule.rule_type
      WHEN 'time_of_day' THEN
        -- Check if session time matches rule
        IF (v_rule.conditions->>'start_time')::TIME <= v_session.time::TIME
           AND (v_rule.conditions->>'end_time')::TIME >= v_session.time::TIME THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        END IF;

      WHEN 'availability' THEN
        -- Check spots remaining
        IF (v_rule.conditions->>'max_spots_remaining')::INTEGER >= v_spots_remaining THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        ELSIF (v_rule.conditions->>'min_capacity_percentage')::DECIMAL <= v_capacity_percentage THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        END IF;

      WHEN 'booking_timing' THEN
        -- Check booking advance time
        IF (v_rule.conditions->>'min_days_advance')::INTEGER * 24 <= v_hours_until_class THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        ELSIF (v_rule.conditions->>'max_hours_advance')::INTEGER >= v_hours_until_class THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        END IF;

      WHEN 'popularity' THEN
        -- Use stored popularity score
        IF v_session.popularity_score >= (v_rule.conditions->>'min_popularity_score')::DECIMAL THEN
          v_total_multiplier := v_total_multiplier * v_rule.multiplier;
        END IF;

    END CASE;
  END LOOP;

  -- Calculate final credits
  v_final_credits := ROUND(v_base_credits * v_total_multiplier);

  -- Ensure within bounds
  v_final_credits := GREATEST(v_min_credits, LEAST(v_max_credits, v_final_credits));

  -- Ensure payout meets rate floor
  -- (This would be checked when booking is created)

  RETURN v_final_credits;
END;
$$;


ALTER FUNCTION "public"."calculate_session_credits"("p_session_id" "uuid", "p_booking_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_expired_subscriptions"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Mark subscriptions as expired
  UPDATE subscriptions
  SET 
    status = 'expired',
    updated_at = NOW()
  WHERE 
    status = 'active'
    AND end_date < NOW();
    
  -- Update user subscription status
  UPDATE users u
  SET 
    subscription_status = 'expired',
    credits = 0,
    updated_at = NOW()
  FROM subscriptions s
  WHERE 
    u.id = s.user_id
    AND s.status = 'expired'
    AND NOT EXISTS (
      SELECT 1 FROM subscriptions s2
      WHERE s2.user_id = u.id
      AND s2.status = 'active'
    );
END;
$$;


ALTER FUNCTION "public"."check_expired_subscriptions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_expired_trials"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Expire trials and remove unused credits
  UPDATE users
  SET 
    subscription_tier = 'inactive',
    subscription_status = 'expired',
    credits = 0
  WHERE 
    subscription_tier = 'free_trial'
    AND trial_end_date < NOW()
    AND subscription_status = 'active';
    
  -- Log expired credits
  INSERT INTO credit_transactions (user_id, transaction_type, credits, balance_after, description)
  SELECT 
    id,
    'expired',
    -credits,
    0,
    'Trial credits expired'
  FROM users
  WHERE 
    subscription_tier = 'inactive'
    AND subscription_status = 'expired'
    AND credits > 0;
END;
$$;


ALTER FUNCTION "public"."check_expired_trials"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_trainer_invite"("p_token" "uuid") RETURNS TABLE("out_gym_trainer_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.gym_trainers;
BEGIN
  SELECT * INTO v_row
  FROM public.gym_trainers
  WHERE invite_token = p_token AND status = 'invited'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invite not found or already used';
  END IF;

  UPDATE public.gym_trainers
  SET user_id = auth.uid(), status = 'active'
  WHERE id = v_row.id;

  RETURN QUERY SELECT v_row.id;
END;
$$;


ALTER FUNCTION "public"."claim_trainer_invite"("p_token" "uuid") OWNER TO "postgres";


