CREATE OR REPLACE FUNCTION "public"."enforce_event_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cap         int;
  going_count int;
BEGIN
  IF NEW.status != 'going' THEN RETURN NEW; END IF;
  SELECT capacity INTO cap FROM public.community_events WHERE id = NEW.event_id;
  IF cap IS NULL THEN RETURN NEW; END IF;
  SELECT count(*) INTO going_count FROM public.community_event_attendees WHERE event_id = NEW.event_id AND status = 'going';
  IF going_count >= cap THEN NEW.status := 'waitlisted'; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_event_capacity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."experience_auto_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  base_slug TEXT;
  candidate TEXT;
  suffix INT;
BEGIN
  IF NEW.slug IS NOT NULL AND NEW.slug <> '' THEN RETURN NEW; END IF;
  base_slug := public.make_slug(COALESCE(NEW.name, 'experience'));
  IF base_slug = '' THEN base_slug := 'experience'; END IF;
  candidate := base_slug;
  suffix := 1;
  WHILE EXISTS (SELECT 1 FROM public.experiences WHERE slug = candidate) LOOP
    candidate := base_slug || '-' || suffix;
    suffix := suffix + 1;
  END LOOP;
  NEW.slug := candidate;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."experience_auto_slug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_community_event_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  base_slug text;
  candidate text;
  counter   int := 0;
BEGIN
  base_slug := trim(both '-' from regexp_replace(lower(NEW.title), '[^a-z0-9]+', '-', 'g'));
  candidate := base_slug;
  LOOP
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.community_events WHERE slug = candidate AND id != NEW.id);
    counter   := counter + 1;
    candidate := base_slug || '-' || counter;
  END LOOP;
  NEW.slug := candidate;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_community_event_slug"() OWNER TO "postgres";


