CREATE OR REPLACE FUNCTION "public"."gym_programme_link_intro"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_programme RECORD;
BEGIN
  SELECT id, gym_id INTO v_programme FROM public.gym_programmes WHERE intro_session_id = NEW.session_id LIMIT 1;
  IF v_programme.id IS NULL THEN RETURN NEW; END IF;

  IF EXISTS (SELECT 1 FROM public.gym_programme_enrollments WHERE intro_booking_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.gym_programme_enrollments
    (programme_id, gym_id, user_id, guest_name, guest_email, guest_phone, intro_booking_id, status)
  VALUES
    (v_programme.id, v_programme.gym_id, NEW.user_id, NEW.guest_name, NEW.guest_email, NEW.guest_phone, NEW.id, 'intro_booked');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."gym_programme_link_intro"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role  text := NEW.raw_user_meta_data->>'role';
  v_name  text := NULLIF(trim(COALESCE(NEW.raw_user_meta_data->>'name', NEW.raw_user_meta_data->>'full_name')), '');
  v_phone text := NULLIF(trim(NEW.raw_user_meta_data->>'phone'), '');
  v_service_role_key text;
BEGIN
  INSERT INTO public.users (
    id, email, name, phone, created_at, updated_at
  )
  VALUES (
    NEW.id, NEW.email, v_name, v_phone, now(), now()
  )
  ON CONFLICT DO NOTHING;  -- catches id AND email unique constraint conflicts

  IF v_role IS DISTINCT FROM 'personal_trainer' AND v_role IS DISTINCT FROM 'partner' THEN
    BEGIN
      v_service_role_key := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
      PERFORM net.http_post(
        url     := public.edge_function_url('notify-user-welcome'),
        headers := jsonb_build_object(
          'Content-Type',  'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        ),
        body    := jsonb_build_object('record', jsonb_build_object('id', NEW.id, 'email', NEW.email, 'name', v_name))
      );
    EXCEPTION WHEN OTHERS THEN
      NULL; -- never block signup if the welcome email fails to fire
    END;
  END IF;

  RETURN NEW;
END;
$$;


