CREATE OR REPLACE FUNCTION "public"."make_slug"("input" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  s TEXT;
BEGIN
  s := LOWER(TRIM(input));
  s := REGEXP_REPLACE(s, '[^a-z0-9\s-]', '', 'g');
  s := REGEXP_REPLACE(s, '[\s]+', '-', 'g');
  s := REGEXP_REPLACE(s, '-+', '-', 'g');
  s := TRIM(s, '-');
  RETURN s;
END;
$$;


ALTER FUNCTION "public"."make_slug"("input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_knowledge_chunks"("query_embedding" "public"."vector", "match_domains" "text"[] DEFAULT NULL::"text"[], "match_status" "text" DEFAULT 'approved'::"text", "match_goals" "text"[] DEFAULT NULL::"text"[], "match_experience_levels" "text"[] DEFAULT NULL::"text"[], "match_activities" "text"[] DEFAULT NULL::"text"[], "match_topics" "text"[] DEFAULT NULL::"text"[], "match_barriers" "text"[] DEFAULT NULL::"text"[], "match_count" integer DEFAULT 20) RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "domain" "text", "title" "text", "heading" "text", "content" "text", "source" "text", "source_type" "text", "version" integer, "metadata" "jsonb", "similarity" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  select
    c.id as chunk_id,
    c.document_id,
    c.domain,
    d.title,
    c.heading,
    c.content,
    d.source,
    d.source_type,
    d.version,
    c.metadata,
    1 - (c.embedding <=> query_embedding) as similarity
  from public.knowledge_chunks c
  join public.knowledge_documents d on d.id = c.document_id
  where d.status = match_status
    and (match_domains is null or c.domain = any(match_domains))
    -- Intersection semantics (section 41), but only once a document actually
    -- declares the field — absence of e.g. `goals` metadata is "no opinion",
    -- not "incompatible" (section 17's "do not require every field"), so an
    -- explicit goal filter never excludes a document that simply never
    -- targeted any goal.
    and (match_goals is null or not (d.metadata ? 'goals') or (d.metadata -> 'goals') ?| match_goals)
    and (match_experience_levels is null or not (d.metadata ? 'experience_levels') or (d.metadata -> 'experience_levels') ?| match_experience_levels)
    and (match_activities is null or not (d.metadata ? 'activities') or (d.metadata -> 'activities') ?| match_activities)
    and (match_topics is null or not (d.metadata ? 'topics') or (d.metadata -> 'topics') ?| match_topics)
    and (match_barriers is null or not (d.metadata ? 'barriers') or (d.metadata -> 'barriers') ?| match_barriers)
  order by c.embedding <=> query_embedding
  limit match_count;
$$;


ALTER FUNCTION "public"."match_knowledge_chunks"("query_embedding" "public"."vector", "match_domains" "text"[], "match_status" "text", "match_goals" "text"[], "match_experience_levels" "text"[], "match_activities" "text"[], "match_topics" "text"[], "match_barriers" "text"[], "match_count" integer) OWNER TO "postgres";


