CREATE OR REPLACE FUNCTION "public"."send_booking_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url          text  := 'https://YOUR_PROJECT_REF.supabase.co/functions/v1/send-email';
  v_key          text  := 'YOUR_SERVICE_ROLE_KEY';
  v_headers      jsonb := jsonb_build_object(
                            'Content-Type', 'application/json',
                            'Authorization', 'Bearer YOUR_SERVICE_ROLE_KEY'
                          );
  v_session      record;
  v_gym          record;
  v_customer     record;
  v_partner_email text;
  v_partner_name  text;
BEGIN
  -- Fetch session + gym details
  SELECT s.name, s.date, s.time, g.id AS gym_id, g.name AS gym_name,
         g.location AS gym_location, g.contact_email
  INTO   v_session
  FROM   sessions s
  JOIN   gyms g ON g.id = s.gym_id
  WHERE  s.id = NEW.session_id;

  -- Fetch customer details
  SELECT email, COALESCE(name, 'there') AS name
  INTO   v_customer
  FROM   users
  WHERE  id = NEW.user_id;

  -- Partner email: prefer gyms.contact_email, fall back to partners table if it exists
  v_partner_email := v_session.contact_email;
  v_partner_name  := v_session.gym_name;

  -- ── Notify partner ──────────────────────────────────────────
  IF v_partner_email IS NOT NULL THEN
    PERFORM net.http_post(
      url     := v_url,
      headers := v_headers,
      body    := jsonb_build_object(
        'type', 'new_booking',
        'data', jsonb_build_object(
          'email',        v_partner_email,
          'businessName', v_partner_name,
          'customerName', v_customer.name,
          'sessionName',  v_session.name,
          'sessionDate',  v_session.date,
          'sessionTime',  v_session.time,
          'sessionId',    NEW.session_id
        )
      )
    );
  END IF;

  -- ── Notify customer (booking confirmation) ───────────────────
  IF v_customer.email IS NOT NULL THEN
    PERFORM net.http_post(
      url     := v_url,
      headers := v_headers,
      body    := jsonb_build_object(
        'type', 'booking_confirmation',
        'data', jsonb_build_object(
          'email',            v_customer.email,
          'customerName',     v_customer.name,
          'sessionName',      v_session.name,
          'sessionDate',      v_session.date,
          'sessionTime',      v_session.time,
          'venueName',        v_session.gym_name,
          'venueLocation',    v_session.gym_location,
          'confirmationCode', NEW.confirmation_code
        )
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."send_booking_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."session_auto_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  base_slug TEXT;
  next_suffix INT;
BEGIN
  IF NEW.slug IS NOT NULL AND NEW.slug <> '' THEN RETURN NEW; END IF;
  base_slug := public.make_slug(COALESCE(NEW.name, 'session'));
  IF base_slug = '' THEN base_slug := 'session'; END IF;

  SELECT COALESCE(MAX(
    CASE WHEN slug = base_slug THEN 0
         ELSE substring(slug from ('^' || base_slug || '-([0-9]+)$'))::int
    END
  ), -1) + 1
  INTO next_suffix
  FROM public.sessions
  WHERE slug = base_slug OR slug ~ ('^' || base_slug || '-[0-9]+$');

  IF next_suffix = 0 THEN
    NEW.slug := base_slug;
  ELSE
    NEW.slug := base_slug || '-' || next_suffix;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."session_auto_slug"() OWNER TO "postgres";


