CREATE OR REPLACE FUNCTION "public"."trigger_pt_invite_received_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _service_role_key text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
BEGIN
  IF NEW.status = 'pending' AND NEW.client_user_id IS NOT NULL THEN
    PERFORM net.http_post(
      url     := public.edge_function_url('notify-pt-client-event'),
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || _service_role_key),
      body    := jsonb_build_object('type', 'invite_received', 'record', row_to_json(NEW))
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_pt_invite_received_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_pt_status_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _service_role_key text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
BEGIN
  IF NEW.status IN ('approved', 'rejected') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    PERFORM net.http_post(
      url     := public.edge_function_url('notify-partner-status'),
      headers := jsonb_build_object(
        'Content-Type',  'application/json',
        'Authorization', 'Bearer ' || _service_role_key
      ),
      body    := jsonb_build_object(
        'type',       'pt_status_change',
        'record',     row_to_json(NEW),
        'old_record', row_to_json(OLD)
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_pt_status_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_workout_assigned_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _service_role_key text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
BEGIN
  IF NEW.assigned_by IS NOT NULL THEN
    PERFORM net.http_post(
      url     := public.edge_function_url('notify-pt-client-event'),
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || _service_role_key),
      body    := jsonb_build_object('type', 'workout_assigned', 'record', row_to_json(NEW))
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_workout_assigned_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_pt_client"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.user_id IS NOT NULL THEN
    INSERT INTO public.pt_clients (pt_id, client_user_id, status)
    VALUES (NEW.pt_id, NEW.user_id, 'active')
    ON CONFLICT (pt_id, client_user_id) DO UPDATE SET status = 'active';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."upsert_pt_client"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_rate_floor"("p_session_id" "uuid", "p_credits_used" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_credit_value DECIMAL;
  v_calculated_payout DECIMAL;
  v_rate_floor DECIMAL;
BEGIN
  -- Get current credit value
  SELECT base_credit_value INTO v_credit_value
  FROM credit_value_settings
  LIMIT 1;

  -- Calculate payout
  v_calculated_payout := p_credits_used * v_credit_value;

  -- Get rate floor
  SELECT g.rate_floor INTO v_rate_floor
  FROM sessions s
  JOIN gyms g ON s.gym_id = g.id
  WHERE s.id = p_session_id;

  -- Verify payout >= floor
  RETURN v_calculated_payout >= v_rate_floor;
END;
$$;


ALTER FUNCTION "public"."verify_rate_floor"("p_session_id" "uuid", "p_credits_used" integer) OWNER TO "postgres";

