CREATE OR REPLACE VIEW "public"."partner_cancellation_metrics" AS
 SELECT "b"."gym_id",
    "g"."name" AS "gym_name",
    "count"(*) AS "total_bookings",
    "count"(*) FILTER (WHERE ("b"."cancelled_by" = 'partner'::"text")) AS "partner_cancellations",
    "count"(*) FILTER (WHERE ("b"."cancelled_by" = 'customer'::"text")) AS "customer_cancellations",
    "count"(*) FILTER (WHERE (("b"."status")::"text" = 'no_show'::"text")) AS "no_shows",
    "round"(((("count"(*) FILTER (WHERE ("b"."cancelled_by" = 'partner'::"text")))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "partner_cancellation_rate_pct"
   FROM ("public"."bookings" "b"
     JOIN "public"."gyms" "g" ON (("g"."id" = "b"."gym_id")))
  GROUP BY "b"."gym_id", "g"."name";


ALTER VIEW "public"."partner_cancellation_metrics" OWNER TO "postgres";


