CREATE OR REPLACE VIEW "public"."pt_profiles_public" AS
 SELECT "pt"."id",
    "pt"."user_id",
    "pt"."full_name",
    "pt"."professional_name",
    "pt"."slug",
    "pt"."photo_url",
    "pt"."bio",
    "pt"."instagram_handle",
    "pt"."phone",
    "pt"."email",
    "pt"."years_of_experience",
    "pt"."certifications",
    "pt"."specialisations",
    "pt"."languages",
    "pt"."training_locations",
    "pt"."session_types",
    "pt"."service_areas",
    "pt"."status",
    "pt"."rejection_reason",
    "pt"."is_certified_verified",
    "pt"."approved_at",
    "pt"."rejected_at",
    "pt"."created_at",
    "pt"."updated_at",
    "round"("avg"("r"."rating"), 1) AS "avg_rating",
    "count"("r"."id") AS "review_count",
    "count"(DISTINCT "b"."id") FILTER (WHERE ("b"."status" = 'completed'::"text")) AS "sessions_completed"
   FROM (("public"."personal_trainers" "pt"
     LEFT JOIN "public"."pt_reviews" "r" ON (("r"."pt_id" = "pt"."id")))
     LEFT JOIN "public"."pt_bookings" "b" ON (("b"."pt_id" = "pt"."id")))
  WHERE ("pt"."status" = 'approved'::"text")
  GROUP BY "pt"."id";



