   FROM "public"."communities"
  WHERE (("communities"."id" = "community_members"."community_id") AND ("communities"."community_type" = 'open'::"text") AND ("communities"."review_status" = 'approved'::"text"))))) OR (("status" = 'pending'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."communities"
  WHERE (("communities"."id" = "community_members"."community_id") AND ("communities"."community_type" = 'approval_required'::"text") AND ("communities"."review_status" = 'approved'::"text"))))))));



