-- ---------------------------------------------------------------------------
-- I0 Phase 5: environment-aware Edge Function URL resolver.
-- Reads the base URL from public.app_settings ('edge_base_url'); when that row
-- is absent (production) it returns the current production base URL, so
-- production behaviour is identical to the previous hard-coded value.
-- Local development inserts the row via supabase/seed.sql.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION "public"."edge_function_url"("fn" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(
           (SELECT "value" FROM "public"."app_settings" WHERE "key" = 'edge_base_url'),
           'https://kdmhmkwzanqnwehcddvr.supabase.co/functions/v1'
         ) || '/' || "fn";
$$;
ALTER FUNCTION "public"."edge_function_url"("fn" "text") OWNER TO "postgres";
